    h = int(observation.get("grid_height", 8))
    resources = observation.get("resources", []) or []
    obstacles = observation.get("obstacles", []) or []

    ob = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                ob.add((x, y))

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def passable(x, y):
        return inb(x, y) and (x, y) not in ob

    def man(a, b, c, d):
        a, b, c, d = abs(a - c), abs(b - d), 0, 0
        return a + b

    parsed_resources = []
    for r in resources:
        if isinstance(r, (list, tuple)) and len(r) >= 2:
            x, y = int(r[0]), int(r[1])
            if 0 <= x < w and 0 <= y < h:
                parsed_resources.append((x, y))
        elif isinstance(r, dict) and "x" in r and "y" in r:
            x, y = int(r["x"]), int(r["y"])
            if 0 <= x < w and 0 <= y < h:
                parsed_resources.append((x, y))

    tx, ty = None, None
    if parsed_resources:
        bestd, tx, ty = 10**9, parsed_resources[0][0], parsed_resources[0][1]
        for x, y in parsed_resources:
            d = abs(sx - x) + abs(sy - y)
            if d < bestd or (d == bestd and (x, y) < (tx, ty)):
                bestd, tx, ty = d, x, y
    else:
        tx, ty = (w - 1) // 2, (h - 1) // 2

