    best_score = -10**18
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not passable(nx, ny):
            continue
        score = - (abs(nx - tx) + abs(ny - ty))
        score += -0.05 * (abs(nx - ox) + abs(ny - oy))
