    for r in resources:
        if not r or len(r) < 2:
            continue
        rx, ry = int(r[0]), int(r[1])
        if valid(rx, ry):
            opp_dists_now.append((md(ox, oy, rx, ry), rx, ry))
    opp_d_now_min = min([d for d, _, _ in opp_dists_now], default=10**9)

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not valid(nx, ny):
            nx, ny, dx, dy = sx, sy, 0, 0

        my_best = 10**9
        opp_best = 10**9
        contest_bonus = 0
        immediate = 0
        center_bias = -abs(nx - cx) - abs(ny - cy)

        for r in resources:
            if not r or len(r) < 2:
                continue
            rx, ry = int(r[0]), int(r[1])
            if not valid(rx, ry):
                continue
            dm_me = md(nx, ny, rx, ry)
            dm_opp = md(ox, oy, rx, ry)
            if dm_me < my_best:
                my_best = dm_me
            if dm_opp < opp_best:
                opp_best = dm_opp
            if dm_me == 0:
