            # contest: if I can be at/inside opponent's current reach for this resource
            dm_opp_now = md(ox, oy, rx, ry)
            if dm_me < dm_opp_now and dm_opp_now <= opp_d_now_min + 1:
                contest_bonus += (opp_d_now_min - dm_opp_now + 1) * 3

